import { rmSync } from "node:fs";
// Only discard files generated by the isolated Next.js verification app.
export default function cleanupGallery() {
  for (const path of [".next", "next-env.d.ts", "AGENTS.md", "CLAUDE.md"]) {
    rmSync(new URL(`./gallery-app/${path}`, import.meta.url), {
      recursive: true,
      force: true,
    });
  }
}
